        ('N2', 'd1000019-0000-0000-0000-000000000021'::uuid, 'GP-JA-N2-004', 'sentence_pattern', 'Tidak Mungkin Bisa / Terikat Etika (~わけにはいかない)', '[Kamus Verba] + わけにはいかない', 'Secara moral, sosial, atau logis tidak dapat melakukan sesuatu meski mungkin sebenarnya ingin.', 4, '[{"jp":"大事な 会議が あるので、休むわけにはいきません。","reading":"Daijina kaigi ga aru node, yasumu wake ni wa ikimasen.","id":"Karena ada rapat penting, saya tidak mungkin libur."},{"jp":"約束したからには、途中で やめるわけにはいかない。","reading":"Yakusoku shita kara ni wa, tochuu de yameru wake ni wa ikanai.","id":"Karena sudah berjanji, tidak bisa berhenti di tengah jalan."}]'::jsonb),
        ('N2', 'd1000019-0000-0000-0000-000000000022'::uuid, 'GP-JA-N2-005', 'sentence_pattern', 'Terpaksa Harus (~ざるを得ない)', '[Bentuk-NAI] (tanpa ない) + ざるを得ない', 'Tidak punya pilihan selain melakukan hal tersebut walaupun berat.', 5, '[{"jp":"予算が 足りないため、計画を 見直さざるを得ない。","reading":"Yosan ga tarinai tame, keikaku o minaosazaru o enai.","id":"Karena anggaran kurang, mau tidak mau rencana harus ditinjau ulang."},{"jp":"安全のため、イベントを 中止せざるを得なかった。","reading":"Anzen no tame, ibento o chuushi sezaru o enakatta.","id":"Demi keamanan, acara terpaksa dibatalkan."}]'::jsonb),
        ('N2', 'd1000019-0000-0000-0000-000000000023'::uuid, 'GP-JA-N2-006', 'sentence_pattern', 'Meskipun / Terlepas Dari (~にもかかわらず)', '[Nomina / Bentuk Biasa] + にもかかわらず', 'Menunjukkan hasil yang bertolak belakang dengan kondisi awal ("meskipun ...").', 6, '[{"jp":"激しい 雨にもかかわらず、多くの 人が 集まった。","reading":"Hageshii ame ni mo kakawarazu, ooku no hito ga atsumatta.","id":"Meskipun hujan deras, banyak orang tetap berkumpul."},{"jp":"注意したにもかかわらず、同じ ミスが 繰り返された。","reading":"Chuui shita ni mo kakawarazu, onaji misu ga kurikaesareta.","id":"Meski sudah diperingatkan, kesalahan yang sama terulang."}]'::jsonb),
        ('N2', 'd1000019-0000-0000-0000-000000000024'::uuid, 'GP-JA-N2-007', 'tense', 'Setelah Mempertimbangkan / Dalam Hal (~上で)', '[Bentuk-TA / Nomina + の] + 上で（うえで）', 'Melakukan langkah pertama secara tuntas sebagai pijakan untuk keputusan atau tindakan berikutnya.', 7, '[{"jp":"契約書の 内容を 確認した上で、署名してください。","reading":"Keiyakusho no naiyou o kakunin shita ue de, shomei shite kudasai.","id":"Setelah memeriksa isi kontrak dengan saksama, silakan tanda tangani."},{"jp":"健康管理の 上でも、睡眠は 重要です。","reading":"Kenkou kanri no ue demo, suimin wa juuyou desu.","id":"Dalam hal menjaga kesehatan pun, tidur sangat penting."}]'::jsonb),
        ('N2', 'd1000019-0000-0000-0000-000000000025'::uuid, 'GP-JA-N2-008', 'tense', 'Sedang Terus Berlangsung (~つつある)', '[Stem Verba] + つつある', 'Menggambarkan tren atau perubahan progresif yang sedang berlangsung secara formal (sering dipakai di berita).', 8, '[{"jp":"地域社会の 高齢化が 進みつつある。","reading":"Chiiki shakai no koureika ga susumitsutsu aru.","id":"Penuaan demografi masyarakat terus bergerak maju."},{"jp":"状況は 少しずつ 改善されつつあります。","reading":"Joukyou wa sukoshizutsu kaizen saretsutsu arimasu.","id":"Situasinya sedikit demi sedikit sedang terus membaik."}]'::jsonb),
        ('N2', 'd1000019-0000-0000-0000-000000000026'::uuid, 'GP-JA-N2-009', 'sentence_pattern', 'Bisa Saja Berakibat Buruk (~かねない)', '[Stem Verba] + かねない', 'Menyatakan kekhawatiran bahwa situasi sekarang berisiko memicu kejadian buruk.', 9, '[{"jp":"確認を 怠ると、大きな 事故に つながりかねない。","reading":"Kakunin o okotaru to, ookina jiko ni tsunagarikanenai.","id":"Jika lalai mengecek, bisa saja memicu kecelakaan besar."},{"jp":"無理な スケジュールは 品質を 損ないかねません。","reading":"Murina sukejuuru wa hinshitsu o sokonaikanemasen.","id":"Jadwal yang dipaksakan berisiko merusak kualitas."}]'::jsonb),
        ('N2', 'd1000019-0000-0000-0000-000000000027'::uuid, 'GP-JA-N2-010', 'honorific', 'Ungkapan Hormat Peninggi (Sonkeigo Baku)', 'お + [Stem] + になる / Verba Khusus', 'Meninggikan posisi lawan bicara, klien, atau atasan dalam percakapan bisnis formal.', 10, '[{"jp":"社長は すでに お帰りになりました。","reading":"Shachou wa sudeni okaeri ni narimashita.","id":"Bapak Direktur sudah pulang terlebih dahulu."},{"jp":"こちらの 資料を ご覧いただけますか。","reading":"Kochira no shiryou o goran itadakemasu ka.","id":"Apakah Anda berkenan melihat dokumen ini?"}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000028'::uuid, 'GP-JA-N1-001', 'tense', 'Hingga Mencapai Titik Kritis (~に至って)', '[Nomina / Kamus Verba] + に至って（にいたって）', 'Menegaskan pencapaian suatu tahap ekstrem setelah melalui proses panjang.', 1, '[{"jp":"事態が 悪化するに至って、ようやく 対策が 取られた。","reading":"Jitai ga akka suru ni itatte, youyaku taisaku ga torareta.","id":"Hingga situasi memburuk barulah langkah penanganan diambil."},{"jp":"この 段階に至っては、方針を 変えられない。","reading":"Kono dankai ni itatte wa, houshin o kaerarenai.","id":"Jika sudah sampai tahap ini, arah kebijakan tak dapat diubah."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000029'::uuid, 'GP-JA-N1-002', 'sentence_pattern', 'Terpaksa Oleh Keadaan Luar (~を余儀なくされる)', '[Nomina] + を余儀なくされる（をよぎなくされる）', 'Bentuk resmi bahwa suatu pihak tidak punya pilihan lain selain menerima keputusan berat karena desakan eksternal.', 2, '[{"jp":"法改正により、企業は 体制の 変更を 余儀なくされた。","reading":"Houkaisei ni yori, kigyou wa taisei no henkou o yoginaku sareta.","id":"Akibat revisi hukum, perusahaan terpaksa mengubah strukturnya."},{"jp":"悪天候のため、計画の 縮小を 余儀なくされている。","reading":"Akutenkou no tame, keikaku no shukushou o yoginaku sarete iru.","id":"Karena cuaca buruk, penyusutan rencana terpaksa dilakukan."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000030'::uuid, 'GP-JA-N1-003', 'sentence_pattern', 'Meskipun Memang Demikian (~とはいえ)', '[Nomina / Bentuk Biasa] + とはいえ', 'Mengakui suatu fakta secara formal namun menyoroti kenyataan yang berlawanan di klausa berikutnya.', 3, '[{"jp":"春になったとはいえ、朝晩は まだ 肌寒い。","reading":"Haru ni natta to wa ie, asaban wa mada hadazamui.","id":"Meski sudah masuk musim semi, pagi dan malam masih terasa dingin."},{"jp":"小規模とはいえ、その 研究の 意義は 大きい。","reading":"Shoukibo to wa ie, sono kenkyuu no igi wa ookii.","id":"Walaupun berskala kecil, makna penelitian itu sangat besar."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000031'::uuid, 'GP-JA-N1-004', 'particle', 'Dengan Sarana Resmi / Batas Waktu (~をもって)', '[Nomina] + をもって', 'Menunjukkan instrumen resmi, cara penyelesaian, atau batas waktu efektif dalam pengumuman resmi.', 4, '[{"jp":"本日をもちまして、本キャンペーンを 終了いたします。","reading":"Honjitsu o mochimashite, hon kyanpeen o shuuryou itashimasu.","id":"Dengan berakhirnya hari ini, kampanye ini resmi ditutup."},{"jp":"書面をもって 結果を 通知いたします。","reading":"Shomen o motte kekka o tsuuchi itashimasu.","id":"Hasil akan diberitahukan secara resmi melalui dokumen tertulis."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000032'::uuid, 'GP-JA-N1-005', 'sentence_pattern', 'Tingkat Ekstrem Tanpa Tandingan (~極まりない)', '[Akar Kata Sifat-Na] + 極まりない（きわまりない）', 'Menekankan sifat ekstrem yang tak terlukiskan lagi (sering untuk kritik formal atau kondisi sangat serius).', 5, '[{"jp":"確認せずに 公開するのは 無責任極まりない。","reading":"Kakunin sezu ni koukai suru no wa musekinin kiwamarinai.","id":"Mempublikasikan tanpa verifikasi adalah tindakan yang luar biasa tidak bertanggung jawab."},{"jp":"深夜の 騒音は 迷惑極まりない 行為だ。","reading":"Shinnya no souon wa meiwaku kiwamarinai koui da.","id":"Kebisingan tengah malam merupakan tindakan yang sangat mengganggu."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000033'::uuid, 'GP-JA-N1-006', 'sentence_pattern', 'Dengan Caranya Sendiri (~なりに)', '[Nomina / Bentuk Biasa] + なりに', 'Mencapai tingkat sebaik mungkin sesuai kapasitas atau kondisi masing-masing.', 6, '[{"jp":"初心者なりに 一生懸命 努力してきました。","reading":"Shoshinsha nari ni isshoukenmei doryoku shite kimashita.","id":"Sesuai kapasitas pemula, saya berusaha sekuat tenaga."},{"jp":"どの 案にも それなりの 利点が ある。","reading":"Dono an ni mo sorenari no riten ga aru.","id":"Setiap proposal punya keunggulannya tersendiri."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000034'::uuid, 'GP-JA-N1-007', 'sentence_pattern', 'Pasti Menimbulkan Efek (~ずにはおかない)', '[Bentuk-NAI] (tanpa ない) + ずにはおかない', 'Menyatakan bahwa sesuatu pasti mendorong atau membuat orang merasakan dampak emosional/tindakan tertentu.', 7, '[{"jp":"その スピーチは 聴衆を 感動させずにはおかなかった。","reading":"Sono supiichi wa choushuu o kandou sasezu ni wa okanakatta.","id":"Pidato itu tak pelak menggugah hati seluruh hadirin."},{"jp":"真実を 知れば、誰もが 驚かずにはおかないだろう。","reading":"Shinjitsu o shireba, daremo ga odorokazu ni wa okanai darou.","id":"Jika mengetahui kebenarannya, siapa pun pasti terkejut."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000035'::uuid, 'GP-JA-N1-008', 'sentence_pattern', 'Jika Sudah Sampai Level (~ともなると)', '[Nomina / Verba Kamus] + ともなると', 'Ketika mencapai posisi, skala, atau musim tingkat tertentu, maka konsekuensi khususnya pun berlaku.', 8, '[{"jp":"プロジェクトの 規模が これほど 大きくともなると、慎重さが 要る。","reading":"Purojekuto no kibo ga kore hodo ookiku tomo naru to, shinchousa ga iru.","id":"Bila skala proyek sudah sebesar ini, diperlukan kehati-hatian tinggi."},{"jp":"経営幹部ともなると、長期的な 視野が 求められる。","reading":"Keiei kanbu tomo naru to, choukiteki na shiya ga motomerareru.","id":"Jika sudah menduduki jajaran eksekutif, dituntut wawasan jangka panjang."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000036'::uuid, 'GP-JA-N1-009', 'particle', 'Tanpa Memandang Kondisi (~いかんによらず)', '[Nomina + の] + いかんによらず / いかんにかかわらず', 'Menyatakan aturan atau keputusan tetap berlaku tidak peduli bagaimana kondisi atau alasannya.', 9, '[{"jp":"理由の いかんによらず、無断欠勤は 認められません。","reading":"Riyuu no ikan ni yorazu, mudan kekkin wa mitomeraremasen.","id":"Terlepas dari apa pun alasannya, ketidakhadiran tanpa izin tidak dibenarkan."},{"jp":"経験の有無の いかんにかかわらず、応募可能です。","reading":"Keiken no umu no ikan ni kakawarazu, oubo kanou desu.","id":"Tanpa memandang ada tidaknya pengalaman, Anda dapat mendaftar."}]'::jsonb),
        ('N1', 'd1000019-0000-0000-0000-000000000037'::uuid, 'GP-JA-N1-010', 'sentence_pattern', 'Layak Untuk (~に足る)', '[Nomina / Verba Kamus] + に足る（にたる）', 'Menyatakan kualitas yang cukup memadai atau pantas untuk dipercaya, dipuji, atau dibahas.', 10, '[{"jp":"彼は 十分に 信頼するに足る 人物だ。","reading":"Kare wa juubun ni shinrai suru ni taru jinbutsu da.","id":"Ia adalah sosok yang sangat layak dipercaya."},{"jp":"それは 議論するに足る 重要な 論点である。","reading":"Sore wa giron suru ni taru juuyouna ronten de aru.","id":"Hal itu merupakan pokok bahasan penting yang layak diperdebatkan."}]'::jsonb)
)
INSERT INTO grammar_points (id, level_id, code, category, title, formula, explanation, order_index, examples)
SELECT
    gs.gp_id,
    pl.id,
    gs.code,
    gs.category,
    gs.title,
    gs.formula,
    gs.explanation,
    gs.order_index,
    gs.examples
FROM gp_seed gs
JOIN proficiency_levels pl ON pl.code = gs.level_code
JOIN languages l ON pl.language_id = l.id AND l.code = 'ja'
ON CONFLICT (level_id, code) DO UPDATE
SET
    title = EXCLUDED.title,
    formula = EXCLUDED.formula,
    explanation = EXCLUDED.explanation,
    examples = EXCLUDED.examples;
